from CTFd.utils.challenges import get_solve_counts_for_challenges
from CTFd.utils.decorators import admins_only

reports = Blueprint("reports", __name__)


@reports.route("/reports/solves")
@admins_only
def solves():
    solve_counts = get_solve_counts_for_challenges(admin=True)
    challenges = Challenges.query.with_entities(Challenges.id, Challenges.name).all()
    return jsonify({name: solve_counts.get(id, 0) for id, name in challenges})
